/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re,ipaddress
zones={}
for i in range(1,50):
 d=Path(f'pc{i}/etc/bind'); c=(d/'named.conf').read_text(); z=re.search(r'zone \"(["'^"]+)"'"',c).group(1); filename=re.search(r'file \"/etc/bind/(["'^"]+)"'"',c).group(1); zones[z]=(i,(d/filename).read_text())
ips={i:re.search(r'inet ([\\d.]+)/',Path(f'pc{i}.startup').read_text()).group(1) for i in range(1,61)}
assert len(zones)==49
count=0
for z,(i,data) in zones.items():
 ns='a.root-servers.' if z=='.' else f'ns.{z}.'
 assert f'@ IN NS {ns}' in data and f'{ns} IN A {ips[i]}' in data
 if z"'!='"'.':
  assert f'@ IN A {ips[i]}' in data
  parent=z.split('.',1)[1] if '.' in z else '.'
  pd=zones[parent][1]; assert f'{z}. IN NS {ns}' in pd and f'{ns} IN A {ips[i]}' in pd
  count+=1
for z in ['company.com','university.edu','dept.company.com','servizi.ministero.gov']:
 i,data=zones[z]; assert f'@ IN MX 10 mail.{z}.' in data and f'mail IN A {ips[i]}' in data
for i in range(51,61): assert f'nameserver {ips[50]}' in Path(f'pc{i}.startup').read_text()
for n in range(1,13):
 data=Path(f'r{n}.startup').read_text(); local=set(re.findall(r'inet (10\\.16\\.\\d+\\.\\d+)/24',data)); localnets={str(ipaddress.ip_interface(ip+'/24').network) for ip in local}; routes=set(re.findall(r'ip route replace (10\\.16\\.\\d+\\.0/24)',data)); missing={f'10.16.{j}.0/24' for j in range(1,16)}-localnets-routes
 assert not missing,(n,missing)
print(f'Validated {len(zones)} zones, {count} delegation/glue pairs, four MX records, ten clients, and router LAN route coverage.')
PY"

